import { z } from "zod";

/**
 * Zod mirrors of every schema in `contracts/content-api/v1/openapi.yaml` (ADR-040). The contract
 * is the source of truth: these are checked against the shared fixtures and against the types
 * generated by `openapi-typescript` (`generated/openapi.ts`), so drift fails the web tests.
 *
 * Every object is strict (unknown keys are rejected), including the base schemas the contract
 * leaves open for `allOf` (DECISIONS 12). Optional properties are `exactOptional`, matching the
 * generated types under `exactOptionalPropertyTypes`.
 */

const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
export const TAG_PATTERN = /^[a-z]+(:[a-z0-9-]{1,80})*$/;

const text = (max: number) => z.string().max(max);
const nullable = <T extends z.ZodType>(schema: T) => z.union([schema, z.null()]);
const httpUrl = (max: number) => z.url({ protocol: /^https?$/ }).max(max);
const dateTime = () => z.iso.datetime({ offset: true });

export const ErrorBody = z.strictObject({ error: text(200) });
export const Slug = z.string().max(80).regex(SLUG_PATTERN);
export const Uuid = z.guid();

export const Choice = z.strictObject({ key: text(40), label: text(80) });

export const postFormats = [
  "executive_briefing",
  "insight_article",
  "point_of_view",
  "engineering_note",
  "guide",
  "research_report",
  "case_derived_insight",
] as const;

export const FormatChoice = z.strictObject({
  key: z.enum(postFormats),
  label: text(80),
  plural: text(80),
  slug: Slug,
});

export const practices = [
  "consulting",
  "engineering",
  "ai_data",
  "experience",
  "managed_services",
  "labs",
] as const;

export const PracticeChoice = z.strictObject({ key: z.enum(practices), label: text(80) });

export const DateValue = z.strictObject({ iso: dateTime(), long: text(40), short: text(20) });

export const Image = z.strictObject({
  url: httpUrl(500),
  alt: text(300),
  width: z.int().min(1).max(10_000),
  height: z.int().min(1).max(10_000),
  caption: nullable(text(300)).exactOptional(),
});

const authorRefShape = {
  id: Uuid,
  slug: Slug,
  name: text(120),
  roleTitle: text(120),
  initials: text(3),
  avatar: nullable(Image),
};
export const AuthorRef = z.strictObject(authorRefShape);
export const AuthorDetail = z.strictObject({
  ...authorRefShape,
  firstName: text(60),
  bioMarkdown: text(5000),
  linkedinUrl: nullable(httpUrl(300)),
});

const topicRefShape = {
  id: Uuid,
  slug: Slug,
  name: text(120),
  kind: z.enum(["topic", "sector"]),
  count: z.int().min(0).exactOptional(),
};
export const TopicRef = z.strictObject(topicRefShape);
export const TopicDetail = z.strictObject({ ...topicRefShape, description: text(1000) });

const postSummaryShape = {
  id: Uuid,
  slug: Slug,
  title: text(200),
  excerpt: text(220),
  format: FormatChoice,
  authors: z.array(AuthorRef).min(1),
  topics: z.array(TopicRef),
  practice: nullable(PracticeChoice),
  cover: nullable(Image),
  publishedAt: DateValue,
  updatedAt: nullable(DateValue),
  readingMinutes: z.int().min(1),
  featured: z.boolean(),
};
export const PostSummary = z.strictObject(postSummaryShape);
export const PostDetail = z.strictObject({
  ...postSummaryShape,
  bodyMarkdown: text(200_000),
  seo: z.strictObject({
    title: text(200),
    description: text(320),
    canonicalUrl: nullable(httpUrl(500)),
    noindex: z.boolean(),
  }),
  cta: z.strictObject({ label: text(80), href: text(300) }),
  related: z.array(PostSummary).max(3),
  lastModified: dateTime(),
});

export const PostPage = z.strictObject({
  items: z.array(PostSummary).max(12),
  page: z.int().min(1),
  pageSize: z.literal(12),
  total: z.int().min(0),
  totalPages: z.int().min(0),
  featured: nullable(PostSummary),
  formats: z.array(FormatChoice.extend({ count: z.int().min(1) })),
  topics: z.array(TopicRef),
});

export const Redirect = z.strictObject({ redirect: Slug });

export const InsightsCopy = z.strictObject({
  heading: text(200),
  intro: text(500),
  editorialNote: text(1000),
});

export const SalaryValue = z.strictObject({
  min: z.int().min(0),
  max: z.int().min(0),
  currency: z.string().regex(/^[A-Z]{3}$/),
  period: z.enum(["year", "day"]),
  label: text(80),
});

const roleSummaryShape = {
  id: Uuid,
  slug: Slug,
  title: text(200),
  practice: PracticeChoice,
  level: nullable(Choice),
  location: text(120),
  workModel: Choice,
  employmentType: Choice,
  salary: nullable(SalaryValue),
  closesAt: nullable(DateValue),
  showOnHome: z.boolean(),
};
export const RoleSummary = z.strictObject(roleSummaryShape);
export const RoleDetail = z.strictObject({
  ...roleSummaryShape,
  state: z.literal("open"),
  summary: text(220),
  sections: z.strictObject({
    about: text(20_000),
    responsibilities: text(20_000),
    requirements: text(20_000),
    niceToHave: text(20_000),
    process: text(20_000),
    equalOpportunities: text(20_000),
  }),
  sponsorship: nullable(Choice),
  apply: z.strictObject({
    mode: z.enum(["form", "external"]),
    externalUrl: nullable(httpUrl(500)),
  }),
  datePosted: DateValue,
  lastModified: dateTime(),
  privacy: z.strictObject({
    noticeUrl: nullable(text(300)),
    noticeVersion: nullable(text(40)),
  }),
});

export const ClosedRole = z.strictObject({
  state: z.literal("closed"),
  slug: Slug,
  title: text(200),
  practice: PracticeChoice,
  closedAt: DateValue,
});

export const CareersCopy = z.strictObject({
  heading: text(200),
  intro: text(1000),
  values: z.array(text(80)).max(20),
  statements: z.array(text(500)).max(10),
  emptyState: text(500),
  associatesLine: nullable(text(500)),
  benefits: text(20_000),
  process: text(20_000),
  salaryPolicy: text(20_000),
  equalOpportunities: text(20_000),
  privacyNoticeUrl: nullable(text(300)),
  privacyNoticeVersion: nullable(text(40)),
  speculativeApplications: z.boolean(),
});

export const CareersPage = z.strictObject({
  copy: CareersCopy,
  groups: z.array(z.strictObject({ practice: PracticeChoice, roles: z.array(RoleSummary).min(1) })),
  total: z.int().min(0),
});

export const HomeInsights = z.strictObject({
  heading: text(200),
  intro: text(500),
  items: z.array(PostSummary).min(1).max(4),
});

export const HomeCareers = z.strictObject({
  heading: text(200),
  intro: text(500),
  roles: z.array(RoleSummary).max(5),
  message: nullable(text(500)),
  associatesLine: nullable(text(500)),
});

export const Home = z.strictObject({
  insights: nullable(HomeInsights),
  careers: nullable(HomeCareers),
});

export const SiteState = z.strictObject({
  insightsOpen: z.boolean(),
  careersOpen: z.boolean(),
  nextDueAt: nullable(dateTime()),
  insights: InsightsCopy,
});

export const Sitemap = z.strictObject({
  entries: z.array(z.strictObject({ path: text(200), lastModified: dateTime() })),
});

export const Preview = z.strictObject({
  entity: z.enum(["post", "role"]),
  status: text(20),
  post: nullable(PostDetail),
  role: nullable(RoleDetail),
});

export const RevalidateRequest = z.strictObject({
  eventId: Uuid,
  kind: z.enum(["publish", "remove"]),
  tags: z.array(z.string().regex(TAG_PATTERN)).min(1).max(64),
  paths: z.array(text(200)).max(64),
});

export const RevalidateResponse = z.strictObject({ revalidated: z.array(z.string()) });

export const renderContexts = ["post", "role", "author", "settings"] as const;

export const RenderRequest = z.strictObject({
  markdown: text(200_000),
  context: z.enum(renderContexts),
});

export const renderWarningCodes = [
  "missing_alt",
  "h1_in_body",
  "image_host",
  "html_stripped",
  "heading_level",
] as const;

export const RenderWarning = z.strictObject({
  code: z.enum(renderWarningCodes),
  message: text(300),
  blocking: z.boolean(),
});

export const RenderResponse = z.strictObject({
  html: z.string(),
  toc: z.array(z.strictObject({ id: text(100), text: text(200), depth: z.int().min(2).max(4) })),
  footnotes: z.int().min(0),
  warnings: z.array(RenderWarning),
});

export const cvMimeTypes = [
  "application/pdf",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
] as const;

export const UploadTicketRequest = z.strictObject({
  roleSlug: Slug,
  filename: z.string().min(1).max(200),
  size: z.int().min(1).max(10_485_760),
  mime: z.enum(cvMimeTypes),
});

export const UploadTicket = z.strictObject({
  uploadId: Uuid,
  uploadUrl: httpUrl(2000),
  method: z.literal("PUT"),
  headers: z.record(z.string(), text(200)),
  expiresAt: dateTime(),
});

export const ApplicationRequest = z.strictObject({
  submissionId: Uuid,
  roleSlug: Slug,
  uploadId: Uuid,
  name: z.string().min(1).max(200),
  email: z.email().max(254),
  phone: text(40).exactOptional(),
  location: text(120).exactOptional(),
  linkedinUrl: text(300).exactOptional(),
  portfolioUrl: text(300).exactOptional(),
  rightToWork: z.enum(["yes", "needs_sponsorship", "prefer_to_discuss"]),
  noticePeriod: text(100).exactOptional(),
  coverNote: text(3000).exactOptional(),
  consent: z.literal(true),
  noticeVersion: text(40),
  source: z.enum(["careers_page", "homepage", "role_page"]),
  clientIp: text(45),
  userAgent: text(300),
});

export const ApplicationAccepted = z.strictObject({
  applicationId: Uuid,
  roleTitle: text(200),
  process: text(20_000),
});

export const applicationErrorCodes = [
  "required",
  "invalid",
  "too_long",
  "upload_missing",
  "upload_type",
  "upload_size",
  "role_closed",
  "rate_limited",
] as const;

export const ApplicationErrors = z.strictObject({
  errors: z.record(z.string(), z.enum(applicationErrorCodes)),
});

// Inline operation responses (fixtures/index.json names them `...Response`).
export const AuthorResponse = z.strictObject({ author: AuthorDetail, posts: z.array(PostSummary) });
export const TopicsResponse = z.strictObject({ topics: z.array(TopicRef) });
export const TopicResponse = z.strictObject({ topic: TopicDetail, posts: PostPage });
export const FeedResponse = z.strictObject({ items: z.array(PostSummary).max(20) });
export const TickResponse = z.strictObject({
  promoted: z.int().min(0),
  closed: z.int().min(0),
  delivered: z.int().min(0),
  nextDueAt: nullable(dateTime()),
});
export const HealthResponse = z.strictObject({ status: z.literal("ok") });

// Union responses (`oneOf` in the contract). Strict objects keep the branches disjoint.
export const PostResponse = z.union([PostDetail, Redirect]);
export const AuthorOrRedirect = z.union([AuthorResponse, Redirect]);
export const RoleResponse = z.union([RoleDetail, ClosedRole, Redirect]);

/** Every named contract schema, by the name used in `fixtures/index.json` and the contract. */
export const contractSchemas = {
  Error: ErrorBody,
  Choice,
  FormatChoice,
  PracticeChoice,
  DateValue,
  Image,
  AuthorRef,
  AuthorDetail,
  TopicRef,
  TopicDetail,
  PostSummary,
  PostDetail,
  PostPage,
  Redirect,
  InsightsCopy,
  SalaryValue,
  RoleSummary,
  RoleDetail,
  ClosedRole,
  CareersCopy,
  CareersPage,
  HomeInsights,
  HomeCareers,
  Home,
  SiteState,
  Sitemap,
  Preview,
  RevalidateRequest,
  RevalidateResponse,
  RenderRequest,
  RenderWarning,
  RenderResponse,
  UploadTicketRequest,
  UploadTicket,
  ApplicationRequest,
  ApplicationAccepted,
  ApplicationErrors,
  AuthorResponse,
  TopicsResponse,
  TopicResponse,
  FeedResponse,
  TickResponse,
} as const;

export type ContractSchemaName = keyof typeof contractSchemas;

export type PostSummaryData = z.infer<typeof PostSummary>;
export type PostDetailData = z.infer<typeof PostDetail>;
export type PostPageData = z.infer<typeof PostPage>;
export type RedirectData = z.infer<typeof Redirect>;
export type AuthorResponseData = z.infer<typeof AuthorResponse>;
export type TopicsResponseData = z.infer<typeof TopicsResponse>;
export type TopicResponseData = z.infer<typeof TopicResponse>;
export type FeedResponseData = z.infer<typeof FeedResponse>;
export type CareersPageData = z.infer<typeof CareersPage>;
export type RoleDetailData = z.infer<typeof RoleDetail>;
export type ClosedRoleData = z.infer<typeof ClosedRole>;
export type HomeData = z.infer<typeof Home>;
export type SiteStateData = z.infer<typeof SiteState>;
export type SitemapData = z.infer<typeof Sitemap>;
export type PreviewData = z.infer<typeof Preview>;
export type RevalidateRequestData = z.infer<typeof RevalidateRequest>;
export type RenderRequestData = z.infer<typeof RenderRequest>;
export type RenderResponseData = z.infer<typeof RenderResponse>;
export type RenderWarningData = z.infer<typeof RenderWarning>;
export type TickResponseData = z.infer<typeof TickResponse>;
export type PostResponseData = z.infer<typeof PostResponse>;
export type AuthorOrRedirectData = z.infer<typeof AuthorOrRedirect>;
export type RoleResponseData = z.infer<typeof RoleResponse>;
